import{z as E,x as p,o as r,c as f,q as l,j as s,D as n,d as t,s as i,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"多项式求逆与除法","description":"","frontmatter":{"title":"多项式求逆与除法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/polynomial-inverse.md","filePath":"cs/polynomial-inverse.md","lastUpdated":1791063341000}'),m={name:"cs/polynomial-inverse.md"};function g(A,a,x,B,u,h){const o=p("Mermaid");return r(),f("div",null,[a[2]||(a[2]=l('<h1 id="多项式求逆与除法" tabindex="-1">多项式求逆与除法 <a class="header-anchor" href="#多项式求逆与除法" aria-label="Permalink to &quot;多项式求逆与除法&quot;">​</a></h1><div class="epigraph"><p>常数项可逆则幂级数可牛顿迭代求逆；多项式除法变成乘逆再截断，复杂度与乘法同阶。</p><footer>—— 据 Kung, On Computing Reciprocals of Power Series, 1974；CLRS 第 30 章整理</footer></div><p>上一课<a href="/cs/ntt">NTT</a>给出精确乘。多项式还要除、求 \\(\\bmod\\)、\\(ln/\\exp\\)。缺口是<strong>乘法级</strong>的求逆：牛顿迭代 \\(g\\leftarrow 2g-fg^2\\)，精度翻倍。不重写 NTT 蝶形。后课 Strassen 换矩阵。本课形式幂级数在 \\(x=0\\) 邻域，次数 \\(n\\) 截断。<span class="marginnote">「\\(fg\\equiv 1 \\pmod{x^n}\\)」翻译成大白话：两个级数相乘后<strong>只看前 \\(n\\) 项</strong>，第 \\(n\\) 项以后统统丢弃——就像小数只保留 \\(n\\) 位有效数字。所以「逆」不必真的乘出 \\(1\\)，只要乘积前面 \\(n\\) 位是 \\(1\\) 后面全是零即可。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(f(0)\\neq 0\\)（或模 \\(p\\) 可逆）。求 \\(g\\) 使 \\(fg\\equiv 1\\pmod{x^n}\\)。牛顿：从 \\(g_0=f(0)^{-1}\\) 起，每次把正确位数加倍，每步一次到两次卷积。总 \\(O(M(n))\\)，\\(M\\) 为乘法复杂度。带余除法：\\(f=qh+r\\)，\\(\\deg r\\lt \\deg h\\)，高次逆用 \\(x^n f(1/x)\\) 的倒数再翻转。</p><p>缺口是牛顿，不是 \\(O(n^2)\\) 的长除。</p><h3 id="牛顿不是数值根查找的同一课" tabindex="-1">牛顿不是数值根查找的同一课 <a class="header-anchor" href="#牛顿不是数值根查找的同一课" aria-label="Permalink to &quot;牛顿不是数值根查找的同一课&quot;">​</a></h3><p>这里在环 \\(k[[x]]/(x^n)\\) 里迭代，精度是次数。数值牛顿解 \\(F(z)=0\\) 是另一对象。同名不同结构。</p><p><span class="marginnote">Kung 1974 幂级数倒数。Sieveking 同类。多项式代数的半 gcd、结果子后课不插。生成函数后课用这些工具。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>求逆牛顿。除法：反转、乘逆、截断、再反转。取模 \\(f\\bmod h\\) 即余式。需要 \\(f\\) 的 \\(\\exp/\\ln\\) 时同样牛顿，本课点名。</p>',11)),(r(),s(d,null,{default:n(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22f%2C%20f(0)%20%E5%8F%AF%E9%80%86%22%5D%20--%3E%20NEW%5B%22%E7%89%9B%E9%A1%BF%E7%BF%BB%E5%80%8D%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20NEW%20--%3E%20INV%5B%22f%5E%7B-1%7D%20mod%20x%5En%22%5D%0A%20%20INV%20--%3E%20DIV%5B%22%E9%99%A4%E6%B3%95%20%2F%20%E5%8F%96%E6%A8%A1%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"除法里的「反转」技巧可以类比十进制小数：\\(1/0.0023\\) 先把小数点位置对齐——把 \\(f\\) 的系数倒过来乘 \\(x^n f(1/x)\\)，就相当于移动小数点，使高次项变成低次项，从而能用「对低次求逆」这件已会的事处理高次，最后再翻转回来对齐商。")],-1)),a[4]||(a[4]=e("p",null,"乘法用 NTT 或 Karatsuba。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"若 \\(fg=1+O(x^m)\\)，则 \\(g'=2g-fg^2\\) 满足 \\(fg'=1+O(x^{2m})\\)。与标量牛顿 \\(x\\leftarrow x(2-ax)\\) 求 \\(1/a\\) 同形。除法高次对齐是多项式的「小数点」。与整数除法 Knuth D：整数牛顿也可到乘法级，本课以多项式为主。",-1)),(r(),s(d,null,{default:n(()=>[i(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%B7%B2%E7%9F%A5%20g%20%E5%AF%B9%E5%89%8D%20m%20%E4%BD%8D%E6%AD%A3%E7%A1%AE%22%5D%20--%3E%20B%5B%22%E8%AE%A1%E7%AE%97%20f%C2%B7g%C2%B2%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%AF%AF%E5%B7%AE%E8%97%8F%E5%9C%A8%E7%AC%AC%20m%20%E5%88%B0%202m%20%E4%BD%8D%22%5D%0A%20%20C%20--%3E%20D%5B%22g%E2%80%B2%20%3D%202g%20%E2%88%92%20f%C2%B7g%C2%B2%22%5D%0A%20%20D%20--%3E%20E%5B%22g%E2%80%B2%20%E5%AF%B9%E5%89%8D%202m%20%E4%BD%8D%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20E%20--%3E%20A%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">数字实例：取 \\(f=1-x\\)，真逆是 \\(1+x+x^2+\\cdots\\)。设 \\(g=1\\)（对 \\(1\\) 位正确），则 \\(fg=1-x\\)，一步得 \\(g&#39;=2\\cdot 1-(1-x)=1+x\\)（对 \\(2\\) 位）；再一步 \\(fg^2=1-x^2\\)，得 \\(g&#39;&#39;=2(1+x)-(1-x)(1+x)^2=1+x+x^2+x^3\\)（对 \\(4\\) 位）。每迭代一次正确位数翻倍，\\(n\\) 位只需 \\(\\log n\\) 步。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多点求值/插值全文（可 \\(O(M(n)\\log n)\\)）。不写因式分解。后课默认：多项式逆、除与乘同阶。下一课 Strassen 矩阵乘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>牛顿把求逆做到乘法级。</li><li>除法 = 反转 + 逆 + 截断。</li><li>次数精度翻倍，总 \\(O(M(n))\\)。</li><li>出处：Kung, 1974；CLRS 第 30 章。</li></ul>',5))])}const _=E(m,[["render",g]]);export{c as __pageData,_ as default};
